function toast(t){document.querySelector('.toast')?.remove();const el=document.createElement('div');el.className='toast';el.setAttribute?.('role','status');el.textContent=t;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3500)}
function show(title,text,opts=[]){opts=opts.filter(o=>!o.hidden);const d=$('#modal');modalFns=opts.map(o=>o.disabled?()=>toast('Сейчас этот вариант недоступен.'):o.fn);d.innerHTML=`<button class="close" onclick="closeModal()" aria-label="Закрыть">×</button><div class="eyebrow">Момент выбора</div><h2>${esc(title)}</h2><p>${esc(text)}</p><div class="options">${opts.map((o,i)=>`<button ${o.disabled?'disabled':''} onclick="choose(${i})">${esc(o.label)}${o.hint?`<small>${esc(o.hint)}</small>`:''}</button>${o.placeReference||''}`).join('')}</div>`;if(!d.open)d.showModal()}
function closeModal(){$('#modal').close()}
function choose(i){const fn=modalFns[i];closeModal();fn?.();if(s){save();render()}}
function act(fn){if(s.dead)return;if(s.energy<1){toast('На этот год сил уже не осталось. Можно перейти к следующему.');return}s.energy--;fn();s.social=clamp(Math.round(s.people.filter(p=>p.alive).reduce((a,p)=>a+p.bond,0)/Math.max(1,s.people.filter(p=>p.alive).length)));save();render()}
